window.MDV_DATA["mdv-styles"] = {"app":"/*\n * mdfolio — 画面の部品（app.css）\n *\n * ヘッダー・サイドバー・目次・メニュー・ダイアログなど、画面の部品の配置と形を決めています。\n * 配色・書体・幅は document.css の変数で変えられるので、通常はこのファイルを編集する必要はありません。\n *\n * MIT License\n */\n\n/* ------------------------------------------------------------------ 土台 */\n\nhtml {\n  -webkit-text-size-adjust: 100%;\n  text-size-adjust: 100%;\n  scroll-padding-top: calc(var(--header-h) + 16px);\n}\n\nbody {\n  margin: 0;\n  background: var(--desk);\n  color: var(--ink);\n  font-family: var(--font-sans);\n  font-size: 16px;\n  line-height: 1.8;\n  overflow-wrap: break-word;\n}\n\n[hidden] { display: none !important; }\n\n.mdv-app {\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n}\n\n.mdv-app :focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n\n.mdv-skip {\n  position: absolute;\n  left: 8px;\n  top: -48px;\n  z-index: 60;\n  padding: 6px 12px;\n  background: var(--accent);\n  color: var(--sheet);\n  border-radius: var(--radius);\n  text-decoration: none;\n}\n.mdv-skip:focus { top: 8px; }\n\n.mdv-icon {\n  width: 20px;\n  height: 20px;\n  flex: none;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.75;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n/* ------------------------------------------------------------------ ボタン */\n\n.mdv-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 40px;\n  padding: 0 18px;\n  border: 1px solid var(--rule);\n  border-radius: var(--radius);\n  background: var(--sheet);\n  color: var(--ink);\n  font: inherit;\n  font-weight: 600;\n  line-height: 1.3;\n  cursor: pointer;\n}\n.mdv-btn:hover { border-color: var(--muted); }\n.mdv-btn[disabled] { opacity: 0.5; cursor: default; }\n\n.mdv-btn-primary {\n  border-color: var(--accent);\n  background: var(--accent);\n  color: var(--sheet);\n}\n.mdv-btn-primary:hover { border-color: var(--accent-strong); background: var(--accent-strong); }\n\n.mdv-btn-quiet {\n  border-color: transparent;\n  background: transparent;\n  color: var(--accent);\n  padding: 0 10px;\n}\n.mdv-btn-quiet:hover { border-color: transparent; background: var(--accent-soft); }\n\n.mdv-iconbtn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 36px;\n  height: 36px;\n  flex: none;\n  padding: 0;\n  border: 0;\n  border-radius: var(--radius);\n  background: transparent;\n  color: var(--ink-soft);\n  cursor: pointer;\n}\n.mdv-iconbtn:hover { background: var(--rule-soft); color: var(--ink); }\n\n/* ------------------------------------------------------------------ ヘッダー */\n\n.mdv-header {\n  position: sticky;\n  top: 0;\n  z-index: 30;\n  height: var(--header-h);\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 0 12px;\n  background: var(--desk);\n  border-bottom: 1px solid var(--rule);\n}\n\n.mdv-title {\n  min-width: 0;\n  margin: 0 auto 0 4px;\n  padding-right: 12px;\n  overflow: hidden;\n  color: var(--ink);\n  font-weight: 700;\n  font-size: 1rem;\n  text-decoration: none;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.mdv-title:hover { color: var(--accent); }\n\n.mdv-search {\n  position: relative;\n  flex: 0 1 440px;\n  min-width: 120px;\n}\n\n.mdv-search-icon {\n  position: absolute;\n  left: 10px;\n  top: 50%;\n  width: 18px;\n  height: 18px;\n  margin-top: -9px;\n  color: var(--muted);\n  pointer-events: none;\n}\n\n.mdv-search-input {\n  width: 100%;\n  height: 36px;\n  box-sizing: border-box;\n  padding: 0 64px 0 36px;\n  border: 1px solid var(--rule);\n  border-radius: var(--radius);\n  background: var(--sheet);\n  color: var(--ink);\n  font: inherit;\n  font-size: 0.9375rem;\n  appearance: none;\n  -webkit-appearance: none;\n}\n.mdv-search-input::placeholder { color: var(--muted); opacity: 1; }\n.mdv-search-input::-webkit-search-cancel-button { -webkit-appearance: none; }\n.mdv-search-input:focus { border-color: var(--accent); outline: 2px solid var(--accent); outline-offset: -1px; }\n\n.mdv-search-kbd {\n  position: absolute;\n  right: 8px;\n  top: 50%;\n  transform: translateY(-50%);\n  padding: 1px 6px;\n  border: 1px solid var(--rule);\n  border-radius: 4px;\n  color: var(--muted);\n  font-family: var(--font-sans);\n  font-size: 0.75rem;\n  line-height: 1.5;\n  pointer-events: none;\n}\n\n.mdv-search-panel {\n  position: absolute;\n  right: 0;\n  top: calc(100% + 6px);\n  z-index: 40;\n  width: min(560px, calc(100vw - 24px));\n  max-height: min(70vh, 640px);\n  overflow: auto;\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n  background: var(--sheet);\n  box-shadow: var(--overlay-shadow);\n}\n\n.mdv-search-list { margin: 0; padding: 6px; list-style: none; }\n\n.mdv-search-item {\n  display: block;\n  padding: 8px 10px;\n  border-radius: var(--radius);\n  color: var(--ink);\n  text-decoration: none;\n  line-height: 1.5;\n}\n.mdv-search-item:hover,\n.mdv-search-item.is-active { background: var(--accent-soft); }\n\n.mdv-search-item-title { display: block; font-weight: 700; }\n.mdv-search-item-path { display: block; color: var(--muted); font-size: 0.8125rem; }\n.mdv-search-item-snippet {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 2;\n  overflow: hidden;\n  margin-top: 2px;\n  color: var(--ink-soft);\n  font-size: 0.875rem;\n}\n\n.mdv-search-empty { margin: 0; padding: 18px 16px; color: var(--muted); }\n\n.mdv-search-foot {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 8px 16px;\n  border-top: 1px solid var(--rule-soft);\n  color: var(--muted);\n  font-size: 0.8125rem;\n}\n\n.mdv-app mark,\n.mdv-hit {\n  padding: 0 1px;\n  border-radius: 2px;\n  background: var(--mark);\n  color: var(--mark-ink);\n}\n\n/* ------------------------------------------------------------------ メニュー */\n\n.mdv-menu-wrap { position: relative; }\n\n.mdv-menu {\n  position: absolute;\n  right: 0;\n  top: calc(100% + 6px);\n  z-index: 40;\n  min-width: 248px;\n  padding: 6px;\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n  background: var(--sheet);\n  box-shadow: var(--overlay-shadow);\n}\n\n.mdv-menu-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  min-height: 38px;\n  box-sizing: border-box;\n  padding: 0 10px;\n  border: 0;\n  border-radius: var(--radius);\n  background: transparent;\n  color: var(--ink);\n  font: inherit;\n  font-size: 0.9375rem;\n  line-height: 1.3;\n  text-align: left;\n  text-decoration: none;\n  cursor: pointer;\n}\n.mdv-menu-item:hover { background: var(--accent-soft); }\n.mdv-menu-item .mdv-icon { width: 18px; height: 18px; color: var(--muted); }\n.mdv-menu-item[aria-checked=\"true\"] .mdv-menu-check { visibility: visible; }\n.mdv-menu-check { margin-left: auto; visibility: hidden; color: var(--accent); }\n.mdv-menu-sep { height: 1px; margin: 6px 4px; background: var(--rule-soft); }\n\n/* ------------------------------------------------------------------ 配置 */\n\n.mdv-body {\n  flex: 1;\n  display: grid;\n  grid-template-columns: var(--side-w) minmax(0, 1fr);\n  align-items: start;\n}\n.mdv-app[data-sidebar=\"closed\"] .mdv-body,\n.mdv-app[data-has-set=\"false\"] .mdv-body { grid-template-columns: minmax(0, 1fr); }\n.mdv-app[data-sidebar=\"closed\"] .mdv-sidebar,\n.mdv-app[data-has-set=\"false\"] .mdv-sidebar,\n.mdv-app[data-has-set=\"false\"] .mdv-btn-sidebar { display: none; }\n\n.mdv-sheet {\n  display: grid;\n  grid-template-columns: minmax(0, var(--content-w)) var(--toc-w);\n  justify-content: center;\n  column-gap: 56px;\n  min-height: calc(100vh - var(--header-h));\n  box-sizing: border-box;\n  padding: 0 40px;\n  background: var(--sheet);\n}\n.mdv-app[data-view=\"welcome\"] .mdv-sheet { grid-template-columns: minmax(0, 1fr); }\n\n.mdv-main {\n  min-width: 0;\n  padding: 28px 0 112px;\n}\n/* 文書を切り替えるたびにフォーカスを移す入れ物なので、枠は表示しない */\n.mdv-app .mdv-main:focus,\n.mdv-app .mdv-main:focus-visible { outline: none; }\n\n/* ------------------------------------------------------------------ サイドバー（綴じ込みの見出しタブ） */\n\n.mdv-sidebar {\n  position: sticky;\n  top: var(--header-h);\n  height: calc(100vh - var(--header-h));\n  box-sizing: border-box;\n  overflow-y: auto;\n  overflow-x: hidden;\n  padding: 12px 0 32px 12px;\n  /* 右端の罫線は枠線ではなく内側の影で描く。表示中の文書のタブがその上に重なって、紙と地続きに見える\n     （枠線の上へはみ出させる方法だと、スクロールバーを常に表示する環境で横スクロールバーが出てしまう） */\n  box-shadow: inset -1px 0 0 var(--rule);\n  font-size: 0.9375rem;\n  line-height: 1.45;\n}\n\n.mdv-side-tabs {\n  display: flex;\n  gap: 4px;\n  margin: 0 12px 10px 0;\n  padding: 3px;\n  border-radius: 8px;\n  background: var(--rule-soft);\n}\n.mdv-side-tab {\n  flex: 1;\n  height: 30px;\n  border: 0;\n  border-radius: var(--radius);\n  background: transparent;\n  color: var(--muted);\n  font: inherit;\n  font-size: 0.875rem;\n  font-weight: 600;\n  cursor: pointer;\n}\n.mdv-side-tab[aria-selected=\"true\"] { background: var(--sheet); color: var(--ink); }\n\n.mdv-tree,\n.mdv-tree ul {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.mdv-tree ul {\n  margin-left: 13px;\n  padding-left: 7px;\n  border-left: 1px solid var(--rule);\n}\n\n.mdv-tree-link,\n.mdv-tree summary,\n.mdv-sidenav a {\n  display: block;\n  position: relative;\n  padding: 6px 12px 6px 10px;\n  border: 1px solid transparent;\n  border-right: 0;\n  border-radius: var(--radius) 0 0 var(--radius);\n  color: var(--ink-soft);\n  text-decoration: none;\n}\n.mdv-tree-link:hover,\n.mdv-tree summary:hover,\n.mdv-sidenav a:hover { color: var(--ink); background: var(--rule-soft); }\n\n.mdv-tree summary {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding-left: 4px;\n  list-style: none;\n  cursor: pointer;\n  font-weight: 600;\n  color: var(--ink);\n}\n.mdv-tree summary::-webkit-details-marker { display: none; }\n.mdv-tree summary .mdv-icon { width: 16px; height: 16px; color: var(--muted); transition: transform 0.12s ease; }\n.mdv-tree details[open] > summary .mdv-icon { transform: rotate(90deg); }\n\n/* 表示中の文書: 紙（本文）と地続きのタブにする */\n.mdv-tree-link[aria-current=\"page\"],\n.mdv-sidenav a[aria-current=\"page\"] {\n  position: relative; /* サイドバー右端の罫線（内側の影）より手前に描く */\n  border-color: var(--rule);\n  background: var(--sheet);\n  color: var(--accent);\n  font-weight: 700;\n  box-shadow: inset 3px 0 0 var(--accent);\n}\n\n.mdv-sidenav { padding-right: 0; }\n.mdv-sidenav ul,\n.mdv-sidenav ol { margin: 0; padding: 0; list-style: none; }\n.mdv-sidenav li > ul,\n.mdv-sidenav li > ol { margin-left: 13px; padding-left: 7px; border-left: 1px solid var(--rule); }\n.mdv-sidenav p { margin: 0; }\n.mdv-sidenav-label,\n.mdv-sidenav > p,\n.mdv-sidenav h1, .mdv-sidenav h2, .mdv-sidenav h3, .mdv-sidenav h4 {\n  display: block;\n  margin: 14px 12px 2px 10px;\n  color: var(--muted);\n  font-size: 0.8125rem;\n  font-weight: 700;\n  line-height: 1.5;\n}\n.mdv-sidenav > :first-child { margin-top: 2px; }\n\n.mdv-scrim {\n  position: fixed;\n  inset: var(--header-h) 0 0 0;\n  z-index: 24;\n  background: var(--scrim);\n}\n\n/* ------------------------------------------------------------------ 目次（紙の余白の書き込み） */\n\n.mdv-toc {\n  position: sticky;\n  top: calc(var(--header-h) + 28px);\n  max-height: calc(100vh - var(--header-h) - 56px);\n  box-sizing: border-box;\n  overflow-y: auto;\n  padding: 2px 0 8px;\n  font-size: 0.875rem;\n  line-height: 1.5;\n}\n.mdv-app[data-view=\"welcome\"] .mdv-toc { display: none; }\n\n.mdv-toc-title {\n  margin: 0 0 8px;\n  color: var(--muted);\n  font-size: 0.8125rem;\n  font-weight: 700;\n}\n\n.mdv-toc-list { margin: 0; padding: 0; list-style: none; border-left: 1px solid var(--rule); }\n.mdv-toc-link {\n  display: block;\n  margin-left: -1px;\n  padding: 3px 0 3px 12px;\n  border-left: 2px solid transparent;\n  color: var(--muted);\n  text-decoration: none;\n}\n.mdv-toc-link:hover { color: var(--ink); }\n.mdv-toc-link.is-current { border-left-color: var(--accent); color: var(--accent); font-weight: 700; }\n.mdv-toc-link[data-depth=\"1\"] { padding-left: 24px; }\n.mdv-toc-link[data-depth=\"2\"] { padding-left: 36px; }\n.mdv-toc-link[data-depth=\"3\"] { padding-left: 48px; }\n\n.mdv-toc-inline {\n  display: none;\n  margin: 0 0 24px;\n  border: 1px solid var(--rule);\n  border-radius: var(--radius);\n  font-size: 0.9375rem;\n}\n.mdv-toc-inline > summary { padding: 8px 14px; font-weight: 700; cursor: pointer; }\n.mdv-toc-inline .mdv-toc-list { margin: 0 14px 12px; }\n\n/* ------------------------------------------------------------------ 文書の上部（パス・更新日時） */\n\n.mdv-doc-meta {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  gap: 4px 16px;\n  margin: 0 0 20px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid var(--rule-soft);\n  color: var(--muted);\n  font-size: 0.8125rem;\n  line-height: 1.5;\n}\n.mdv-doc-path { min-width: 0; }\n.mdv-doc-sep { margin: 0 0.4em; color: var(--rule); }\n\n.mdv-notice {\n  margin: 0 0 20px;\n  padding: 10px 14px;\n  border-left: 3px solid var(--warning);\n  background: var(--code-bg);\n  color: var(--ink-soft);\n  font-size: 0.9375rem;\n}\n\n/* ------------------------------------------------------------------ 開始画面（トンボ付きの用紙） */\n\n.mdv-welcome {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  min-height: calc(100vh - var(--header-h) - 140px);\n  padding: 48px 40px;\n}\n\n.mdv-crop {\n  position: relative;\n  width: 100%;\n  max-width: 660px;\n  box-sizing: border-box;\n  padding: 48px 52px 44px;\n  transition: background-color 0.15s ease;\n}\n\n/* トンボ: 角の外側に、角に触れない 2 本の線 */\n.mdv-crop-mark { position: absolute; width: 0; height: 0; color: var(--muted); transition: transform 0.18s ease, color 0.18s ease; }\n.mdv-crop-mark::before,\n.mdv-crop-mark::after { content: \"\"; position: absolute; background: currentColor; }\n.mdv-crop-mark::before { width: 22px; height: 1px; }\n.mdv-crop-mark::after { width: 1px; height: 22px; }\n.mdv-crop-tl { left: 0; top: 0; }\n.mdv-crop-tl::before { right: 9px; top: 0; }\n.mdv-crop-tl::after { left: 0; bottom: 9px; }\n.mdv-crop-tr { right: 0; top: 0; }\n.mdv-crop-tr::before { left: 9px; top: 0; }\n.mdv-crop-tr::after { right: 0; bottom: 9px; }\n.mdv-crop-bl { left: 0; bottom: 0; }\n.mdv-crop-bl::before { right: 9px; bottom: 0; }\n.mdv-crop-bl::after { left: 0; top: 9px; }\n.mdv-crop-br { right: 0; bottom: 0; }\n.mdv-crop-br::before { left: 9px; bottom: 0; }\n.mdv-crop-br::after { right: 0; top: 9px; }\n\n/* ドロップ中: トンボが角に寄り、用紙に色がつく */\n.mdv-app.is-dragover .mdv-crop { background: var(--accent-soft); }\n.mdv-app.is-dragover .mdv-crop-mark { color: var(--accent); }\n.mdv-app.is-dragover .mdv-crop-tl { transform: translate(9px, 9px); }\n.mdv-app.is-dragover .mdv-crop-tr { transform: translate(-9px, 9px); }\n.mdv-app.is-dragover .mdv-crop-bl { transform: translate(9px, -9px); }\n.mdv-app.is-dragover .mdv-crop-br { transform: translate(-9px, -9px); }\n\n.mdv-welcome-title {\n  margin: 0 0 20px;\n  font-family: var(--font-display);\n  font-size: clamp(1.75rem, 1.1rem + 2.2vw, 2.5rem);\n  font-weight: 700;\n  line-height: 1.45;\n  letter-spacing: 0.02em;\n}\n.mdv-welcome-lead { margin: 0 0 28px; max-width: 34em; color: var(--ink-soft); }\n.mdv-welcome-actions { display: flex; flex-wrap: wrap; gap: 12px; margin: 0 0 16px; }\n.mdv-welcome-last { margin: 0 0 16px -10px; }\n.mdv-welcome-pending { margin: 0 0 16px; color: var(--muted); font-size: 0.875rem; }\n.mdv-welcome-hint { margin: 16px 0 0; max-width: 34em; color: var(--ink-soft); font-size: 0.875rem; }\n.mdv-welcome-foot { margin: 28px 0 0; font-size: 0.9375rem; }\n.mdv-welcome-foot a { color: var(--accent); text-underline-offset: 0.2em; }\n\n.mdv-dropveil {\n  position: fixed;\n  inset: 0;\n  z-index: 50;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: var(--scrim);\n  pointer-events: none;\n}\n.mdv-dropveil-box {\n  padding: 28px 44px;\n  border-radius: 8px;\n  background: var(--sheet);\n  color: var(--ink);\n  font-family: var(--font-display);\n  font-size: 1.375rem;\n  font-weight: 700;\n  box-shadow: var(--overlay-shadow);\n}\n\n/* ------------------------------------------------------------------ ダイアログ・通知 */\n\n.mdv-dialog {\n  width: min(560px, calc(100vw - 32px));\n  max-height: calc(100vh - 48px);\n  box-sizing: border-box;\n  padding: 0;\n  border: 1px solid var(--rule);\n  border-radius: 10px;\n  background: var(--sheet);\n  color: var(--ink);\n  box-shadow: var(--overlay-shadow);\n}\n.mdv-dialog::backdrop { background: var(--scrim); }\n.mdv-dialog-wide { width: min(760px, calc(100vw - 32px)); }\n\n.mdv-dialog-form { display: flex; flex-direction: column; max-height: calc(100vh - 50px); margin: 0; }\n.mdv-dialog-head { padding: 22px 26px 0; }\n.mdv-dialog-title { margin: 0 0 6px; font-family: var(--font-display); font-size: 1.375rem; font-weight: 700; line-height: 1.4; }\n.mdv-dialog-lead { margin: 0; color: var(--ink-soft); font-size: 0.9375rem; }\n.mdv-dialog-body { min-height: 0; overflow: auto; padding: 18px 26px 4px; }\n.mdv-dialog-body:empty { padding-top: 0; }\n.mdv-dialog-note { margin: 0; font-size: 0.9375rem; }\n.mdv-dialog-foot { display: flex; justify-content: flex-end; gap: 10px; padding: 18px 26px 22px; }\n\n.mdv-field { display: block; margin: 0 0 16px; }\n.mdv-field-label { display: block; margin: 0 0 6px; font-size: 0.875rem; font-weight: 700; }\n.mdv-input {\n  width: 100%;\n  height: 40px;\n  box-sizing: border-box;\n  padding: 0 12px;\n  border: 1px solid var(--rule);\n  border-radius: var(--radius);\n  background: var(--sheet);\n  color: var(--ink);\n  font: inherit;\n}\n.mdv-input:focus { border-color: var(--accent); }\n\n.mdv-export-summary { margin: 0 0 8px; color: var(--ink-soft); font-size: 0.9375rem; }\n.mdv-export-warn { margin: 0 0 8px; color: var(--warning); font-size: 0.9375rem; }\n\n.mdv-licenses {\n  margin: 0;\n  padding: 14px 16px;\n  border: 1px solid var(--rule-soft);\n  border-radius: var(--radius);\n  background: var(--code-bg);\n  font-family: var(--font-mono);\n  font-size: 0.8125rem;\n  line-height: 1.55;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.mdv-toasts {\n  position: fixed;\n  left: 50%;\n  bottom: 24px;\n  z-index: 70;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  width: max-content;\n  max-width: calc(100vw - 32px);\n  transform: translateX(-50%);\n  pointer-events: none;\n}\n.mdv-toast {\n  max-width: 100%;\n  box-sizing: border-box;\n  padding: 10px 18px;\n  border-radius: 8px;\n  background: var(--toast-bg);\n  color: var(--toast-ink);\n  font-size: 0.9375rem;\n  line-height: 1.5;\n  box-shadow: var(--overlay-shadow);\n  pointer-events: auto;\n}\n.mdv-toast-error { box-shadow: var(--overlay-shadow), inset 4px 0 0 var(--caution); }\n\n.mdv-hidden-input { position: absolute; width: 1px; height: 1px; overflow: hidden; opacity: 0; pointer-events: none; }\n/* コピー用の一時的な入力欄。画面に固定して、選択のときに画面が動かないようにする */\n.mdv-copy-buffer {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 1px;\n  height: 1px;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  overflow: hidden;\n  opacity: 0;\n  pointer-events: none;\n  font-size: 16px;\n  resize: none;\n}\n\n/* ------------------------------------------------------------------ 画面幅による切り替え */\n\n@media (max-width: 1199px) {\n  .mdv-sheet { grid-template-columns: minmax(0, var(--content-w)); }\n  .mdv-toc { display: none; }\n  .mdv-toc-inline { display: block; }\n}\n\n@media (max-width: 799px) {\n  .mdv-body,\n  .mdv-app[data-sidebar=\"closed\"] .mdv-body { grid-template-columns: minmax(0, 1fr); }\n  .mdv-sheet { padding: 0 20px 0 28px; }\n  .mdv-welcome { padding: 32px 16px; }\n  .mdv-crop { padding: 36px 28px 32px; }\n  .mdv-title { max-width: 34vw; }\n  .mdv-search-kbd { display: none; }\n  .mdv-search-input { padding-right: 12px; }\n  .mdv-search-panel { position: fixed; left: 12px; right: 12px; top: calc(var(--header-h) + 4px); width: auto; }\n\n  .mdv-sidebar,\n  .mdv-app[data-sidebar=\"closed\"] .mdv-sidebar {\n    display: block;\n    position: fixed;\n    left: 0;\n    top: var(--header-h);\n    bottom: 0;\n    z-index: 26;\n    width: min(86vw, 320px);\n    height: auto;\n    background: var(--desk);\n    transform: translateX(-100%);\n    transition: transform 0.18s ease;\n    visibility: hidden;\n  }\n  .mdv-app.is-drawer-open .mdv-sidebar { transform: none; visibility: visible; }\n  .mdv-app[data-has-set=\"false\"] .mdv-sidebar { display: none; }\n}\n\n@media (min-width: 800px) {\n  .mdv-scrim { display: none !important; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .mdv-app *,\n  .mdv-app *::before,\n  .mdv-app *::after { transition: none !important; animation: none !important; scroll-behavior: auto !important; }\n}\n\n/* ------------------------------------------------------------------ 印刷: 本文のみ、常にライト配色 */\n\n@media print {\n  body { background: #FFFFFF; }\n  .mdv-header, .mdv-sidebar, .mdv-toc, .mdv-toc-inline, .mdv-scrim, .mdv-toasts, .mdv-dropveil,\n  .mdv-skip, .mdv-copy, .mdv-anchor, .mdv-doc-meta, .mdv-dialog { display: none !important; }\n  .mdv-app, .mdv-body, .mdv-sheet { display: block; min-height: 0; padding: 0; }\n  .mdv-main { padding: 0; }\n}\n","document":"/*\n * mdfolio — 本文と配色（document.css）\n *\n * 見た目を変えるときは、このファイルを編集します。\n *\n *   1. 配色・書体・幅 … 下の「変数」を変えると、本文と画面全体の両方に反映されます。\n *      ライト（:root）とダーク（[data-theme=\"dark\"]）の 2 か所があります。\n *      図（Mermaid）の色も、ここの変数から取ります。\n *   2. 本文の見た目 … 「本文」以降の規則を変えます。本文は .mdv-prose の中にあり、\n *      Markdown から作られる普通の HTML（h1〜h6, p, a, ul, ol, table, pre, code, blockquote など）です。\n *   3. 印刷 … 末尾の @media print で、印刷するときの配色を決めています。\n *\n * 注意\n *   - 文字と背景の色の差（コントラスト）は 4.5:1 以上を目安にしてください。\n *   - url() で外部のアドレス（http:// や https://）を書かないでください。\n *     外部の画像を表示しない設定のときは読み込まれず、設定によっては外部に通信が発生します。\n *   - .mdv- で始まるクラス名のうち、この中に出てくるもの以外は、今後の版で変わることがあります。\n *   - フォルダ版で「サイトとして書き出す」と、このファイルの写し（data/styles.js）が使われます。\n *     編集したあとは、node tools/update.mjs を実行してから書き出してください。\n *\n * mdfolio — document body and colors (document.css)\n *\n * Edit this file to change the look.\n *\n *   1. Colors, fonts, widths … Changing the variables below affects both the document body and the\n *      whole screen. There are two places: light (:root) and dark ([data-theme=\"dark\"]).\n *      Diagrams (Mermaid) take their colors from these variables too.\n *   2. Document body … Change the rules from the \"Document body\" section onward. The body is inside\n *      .mdv-prose and is ordinary HTML made from Markdown (h1–h6, p, a, ul, ol, table, pre, code,\n *      blockquote and so on).\n *   3. Printing … @media print at the end sets the colors used when printing.\n *\n * Notes\n *   - Keep the contrast between text and background at 4.5:1 or more.\n *   - Do not write external addresses (http:// or https://) in url(). They are not loaded while\n *     external images are turned off, and with some settings they cause network access.\n *   - Of the class names starting with .mdv-, those not used in this file may change in future versions.\n *   - In the folder version, \"Export as site\" uses a copy of this file (data/styles.js).\n *     After editing, run node tools/update.mjs before exporting.\n *\n * MIT License\n */\n\n/* ------------------------------------------------------------------ 変数 / Variables */\n\n:root {\n  --font-sans: \"Segoe UI\", \"Helvetica Neue\", \"BIZ UDPGothic\", \"Hiragino Sans\", \"Hiragino Kaku Gothic ProN\", \"Yu Gothic UI\", Meiryo, \"Noto Sans CJK JP\", \"Noto Sans JP\", sans-serif;\n  --font-display: \"BIZ UDPMincho\", \"Hiragino Mincho ProN\", \"Yu Mincho\", \"Noto Serif CJK JP\", \"Noto Serif JP\", Georgia, serif;\n  --font-mono: \"Cascadia Mono\", \"Cascadia Code\", Consolas, \"SFMono-Regular\", Menlo, \"BIZ UDGothic\", \"MS Gothic\", \"Noto Sans Mono CJK JP\", monospace;\n  --header-h: 52px;\n  --side-w: 288px;\n  --toc-w: 232px;\n  --content-w: 50rem;\n  --radius: 6px;\n\n  /* 机（地）と紙、墨、藍 */\n  --desk: #EDF1F5;\n  --sheet: #FFFFFF;\n  --ink: #17202B;\n  --ink-soft: #3A4654;\n  --muted: #5A6878;\n  --rule: #D3DAE3;\n  --rule-soft: #E6EAEF;\n  --accent: #1D4F91;\n  --accent-strong: #163D72;\n  --accent-soft: #E3ECF8;\n  --mark: #FFE27A;\n  --mark-ink: #2B2300;\n  --code-bg: #F2F5F8;\n  --overlay-shadow: 0 14px 36px rgba(15, 23, 34, 0.18);\n  --scrim: rgba(15, 23, 34, 0.42);\n  --toast-bg: #17202B;\n  --toast-ink: #FFFFFF;\n\n  --note: #1D4F91;\n  --tip: #1B7F5A;\n  --important: #6B4BA8;\n  --warning: #8A5A00;\n  --caution: #B3261E;\n\n  --hl-keyword: #8A2D6B;\n  --hl-string: #1B6B4A;\n  --hl-number: #9A4E00;\n  --hl-comment: #5C6A7B;\n  --hl-title: #1D4F91;\n  --hl-attr: #0B6E80;\n  --hl-builtin: #6B4BA8;\n  --hl-add-bg: #DDF3E4;\n  --hl-del-bg: #FBE3E1;\n\n  color-scheme: light;\n}\n\n[data-theme=\"dark\"] {\n  --desk: #0F1722;\n  --sheet: #151F2C;\n  --ink: #DCE4EE;\n  --ink-soft: #C2CCD8;\n  --muted: #93A1B2;\n  --rule: #2A3646;\n  --rule-soft: #212C3A;\n  --accent: #8AB8F2;\n  --accent-strong: #A9CBF6;\n  --accent-soft: #1D2D42;\n  --mark: #6B5300;\n  --mark-ink: #FFF3C4;\n  --code-bg: #1B2736;\n  --overlay-shadow: 0 14px 36px rgba(0, 0, 0, 0.5);\n  --scrim: rgba(0, 0, 0, 0.55);\n  --toast-bg: #DCE4EE;\n  --toast-ink: #151F2C;\n\n  --note: #8AB8F2;\n  --tip: #6FD3A8;\n  --important: #C3A6F5;\n  --warning: #F2B872;\n  --caution: #F2A19B;\n\n  --hl-keyword: #F29BCF;\n  --hl-string: #8FD9A8;\n  --hl-number: #F2B872;\n  --hl-comment: #8D9BAC;\n  --hl-title: #8AB8F2;\n  --hl-attr: #7FD4E0;\n  --hl-builtin: #C3A6F5;\n  --hl-add-bg: #17382A;\n  --hl-del-bg: #45211F;\n\n  color-scheme: dark;\n}\n\n/* ------------------------------------------------------------------ 本文の文字\n\n.mdv-prose {\n  font-family: var(--font-sans);\n  font-size: 1rem;\n  line-height: 1.8;\n}\n\n/* ------------------------------------------------------------------ 本文 / Document body */\n\n/* 本文は自分の枠の外に描画させない（利用者の HTML がアプリの部品に重ならないように）。\n   見出しの四角とフォーカス枠のぶんだけ、枠を外側に広げておく */\n.mdv-prose { contain: paint; margin: -4px -6px -4px -28px; padding: 4px 6px 4px 28px; }\n.mdv-prose > :first-child { margin-top: 0; }\n.mdv-prose > :last-child { margin-bottom: 0; }\n\n.mdv-prose h1,\n.mdv-prose h2,\n.mdv-prose h3,\n.mdv-prose h4,\n.mdv-prose h5,\n.mdv-prose h6 {\n  position: relative;\n  margin: 2em 0 0.7em;\n  color: var(--ink);\n  font-weight: 700;\n  line-height: 1.4;\n}\n.mdv-prose h1 { margin-top: 1.6em; font-size: 2rem; line-height: 1.3; letter-spacing: 0.01em; }\n.mdv-prose h2 { margin-top: 2.2em; font-size: 1.5rem; }\n.mdv-prose h3 { font-size: 1.25rem; }\n.mdv-prose h4 { font-size: 1.0625rem; }\n.mdv-prose h5,\n.mdv-prose h6 { font-size: 1rem; color: var(--ink-soft); }\n\n/* 「■ 見出し」: 余白にぶら下げる小さな四角 */\n.mdv-prose h2::before {\n  content: \"\";\n  position: absolute;\n  left: -1.05em;\n  top: 0.48em;\n  width: 0.46em;\n  height: 0.46em;\n  background: var(--accent);\n}\n\n.mdv-anchor {\n  margin-left: 0.4em;\n  color: var(--muted);\n  font-weight: 400;\n  text-decoration: none;\n  opacity: 0;\n}\n.mdv-prose :is(h1, h2, h3, h4, h5, h6):hover .mdv-anchor,\n.mdv-anchor:focus-visible { opacity: 1; }\n.mdv-anchor:hover { color: var(--accent); }\n\n.mdv-prose p,\n.mdv-prose ul,\n.mdv-prose ol,\n.mdv-prose dl,\n.mdv-prose blockquote,\n.mdv-prose pre,\n.mdv-prose table,\n.mdv-prose figure,\n.mdv-prose details { margin: 0 0 1.15em; }\n\n.mdv-prose a { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.2em; }\n.mdv-prose a:hover { color: var(--accent-strong); text-decoration-thickness: 2px; }\n.mdv-prose a.mdv-missing { color: var(--caution); text-decoration-style: dashed; }\n.mdv-prose a.mdv-ext::after { content: \"\\2197\"; margin-left: 0.15em; font-size: 0.8em; text-decoration: none; display: inline-block; }\n\n.mdv-prose strong { font-weight: 700; }\n.mdv-prose ul,\n.mdv-prose ol { padding-left: 1.6em; }\n.mdv-prose li { margin: 0.25em 0; }\n.mdv-prose li > ul,\n.mdv-prose li > ol { margin: 0.25em 0; }\n.mdv-prose li > p { margin: 0.4em 0; }\n\n.mdv-prose .contains-task-list { padding-left: 0.2em; list-style: none; }\n.mdv-prose .task-list-item { padding-left: 1.6em; text-indent: -1.6em; }\n.mdv-prose .task-list-item > * { text-indent: 0; }\n.mdv-prose .task-list-item input { width: 1em; height: 1em; margin: 0 0.6em 0 0; vertical-align: -0.12em; accent-color: var(--accent); }\n\n.mdv-prose blockquote {\n  padding: 2px 0 2px 16px;\n  border-left: 3px solid var(--rule);\n  color: var(--ink-soft);\n}\n.mdv-prose blockquote > :last-child { margin-bottom: 0; }\n\n.mdv-prose hr { height: 1px; margin: 2.4em 0; border: 0; background: var(--rule); }\n\n.mdv-prose img,\n.mdv-prose video { max-width: 100%; height: auto; vertical-align: middle; }\n.mdv-prose audio { max-width: 100%; }\n\n.mdv-prose kbd {\n  padding: 1px 6px;\n  border: 1px solid var(--rule);\n  border-bottom-width: 2px;\n  border-radius: 4px;\n  background: var(--sheet);\n  font-family: var(--font-mono);\n  font-size: 0.85em;\n}\n\n.mdv-prose details { padding: 8px 14px; border: 1px solid var(--rule); border-radius: var(--radius); }\n.mdv-prose details > summary { font-weight: 700; cursor: pointer; }\n.mdv-prose details[open] > summary { margin-bottom: 8px; }\n.mdv-prose details > :last-child { margin-bottom: 0; }\n\n.mdv-prose sup,\n.mdv-prose sub { line-height: 0; }\n\n.mdv-prose .footnotes-sep { margin-top: 3em; }\n.mdv-prose .footnotes { color: var(--ink-soft); font-size: 0.9375rem; }\n.mdv-prose .footnote-ref a { text-decoration: none; }\n/* 数式のエラー表示の色は、テーマに合わせる（KaTeX は固定の色を style に書く） */\n.mdv-prose .katex-error { color: var(--caution) !important; }\n\n/* 表 */\n\n.mdv-table-wrap { margin: 0 0 1.15em; overflow-x: auto; }\n.mdv-table-wrap > table { margin: 0; }\n\n.mdv-prose table {\n  border-collapse: collapse;\n  font-size: 0.9375rem;\n  line-height: 1.6;\n}\n.mdv-prose th,\n.mdv-prose td { padding: 7px 14px; border-bottom: 1px solid var(--rule); vertical-align: top; }\n.mdv-prose th { border-bottom: 2px solid var(--ink-soft); font-weight: 700; text-align: left; white-space: nowrap; }\n.mdv-prose tbody tr:last-child td { border-bottom-color: var(--ink-soft); }\n\n/* コード */\n\n.mdv-prose code,\n.mdv-prose pre,\n.mdv-plain { font-family: var(--font-mono); }\n\n.mdv-prose :not(pre) > code {\n  padding: 0.12em 0.36em;\n  border-radius: 4px;\n  background: var(--code-bg);\n  font-size: 0.875em;\n}\n\n.mdv-code {\n  margin: 0 0 1.15em;\n  border: 1px solid var(--rule-soft);\n  border-radius: var(--radius);\n  background: var(--code-bg);\n}\n.mdv-code-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  min-height: 30px;\n  padding: 0 4px 0 14px;\n  border-bottom: 1px solid var(--rule-soft);\n  color: var(--muted);\n  font-size: 0.75rem;\n  line-height: 1.4;\n}\n.mdv-copy {\n  height: 24px;\n  padding: 0 8px;\n  border: 0;\n  border-radius: 4px;\n  background: transparent;\n  color: var(--muted);\n  font: inherit;\n  cursor: pointer;\n}\n.mdv-copy:hover { background: var(--rule-soft); color: var(--ink); }\n\n.mdv-prose pre,\n.mdv-plain {\n  margin: 0;\n  padding: 12px 14px;\n  overflow-x: auto;\n  font-size: 0.875rem;\n  line-height: 1.6;\n  tab-size: 4;\n}\n.mdv-prose > pre,\n.mdv-prose :not(.mdv-code) > pre {\n  margin: 0 0 1.15em;\n  border: 1px solid var(--rule-soft);\n  border-radius: var(--radius);\n  background: var(--code-bg);\n}\n.mdv-plain { white-space: pre-wrap; word-break: break-all; }\n\n.hljs-keyword, .hljs-selector-tag, .hljs-literal, .hljs-doctag, .hljs-meta .hljs-keyword { color: var(--hl-keyword); }\n.hljs-string, .hljs-regexp, .hljs-char, .hljs-template-variable, .hljs-addition { color: var(--hl-string); }\n.hljs-number, .hljs-symbol, .hljs-bullet, .hljs-variable.constant_ { color: var(--hl-number); }\n.hljs-comment, .hljs-quote, .hljs-meta { color: var(--hl-comment); }\n.hljs-title, .hljs-section, .hljs-name, .hljs-selector-id, .hljs-selector-class { color: var(--hl-title); }\n.hljs-attr, .hljs-attribute, .hljs-property, .hljs-variable, .hljs-params .hljs-attr { color: var(--hl-attr); }\n.hljs-built_in, .hljs-type, .hljs-class .hljs-title, .hljs-title.class_ { color: var(--hl-builtin); }\n.hljs-emphasis { font-style: italic; }\n.hljs-strong { font-weight: 700; }\n.hljs-addition { background: var(--hl-add-bg); }\n.hljs-deletion { background: var(--hl-del-bg); color: var(--caution); }\n.hljs-link { text-decoration: underline; }\n\n/* アラート */\n\n.markdown-alert {\n  margin: 0 0 1.15em;\n  padding: 10px 16px;\n  border-left: 3px solid var(--alert, var(--note));\n  background: var(--code-bg);\n}\n.markdown-alert > :last-child { margin-bottom: 0; }\n.mdv-prose .markdown-alert-title { margin: 0 0 4px; color: var(--alert, var(--note)); font-weight: 700; }\n.markdown-alert-note { --alert: var(--note); }\n.markdown-alert-tip { --alert: var(--tip); }\n.markdown-alert-important { --alert: var(--important); }\n.markdown-alert-warning { --alert: var(--warning); }\n.markdown-alert-caution { --alert: var(--caution); }\n\n/* 数式・図 */\n\n.math-display,\n.math-inline-display { display: block; margin: 1em 0; overflow-x: auto; overflow-y: hidden; text-align: center; }\n.mdv-math-raw { font-family: var(--font-mono); font-size: 0.875em; color: var(--ink-soft); }\n.katex { font-size: 1.1em; }\n\n.mdv-mermaid { margin: 0 0 1.15em; overflow-x: auto; text-align: center; }\n.mdv-mermaid svg { max-width: 100%; height: auto; }\n.mdv-mermaid-error {\n  margin: 0 0 1.15em;\n  border: 1px solid var(--rule);\n  border-left: 3px solid var(--caution);\n  border-radius: var(--radius);\n}\n.mdv-mermaid-error-title { margin: 0; padding: 8px 14px 0; color: var(--caution); font-weight: 700; }\n.mdv-mermaid-error-msg { margin: 0; padding: 0 14px 8px; color: var(--ink-soft); font-size: 0.875rem; white-space: pre-wrap; }\n.mdv-prose .mdv-mermaid-error > pre { margin: 0; border: 0; border-top: 1px solid var(--rule-soft); border-radius: 0; }\n\n/* プレースホルダ（見つからない画像・ブロックした外部画像） */\n\n.mdv-ph {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  max-width: 100%;\n  box-sizing: border-box;\n  padding: 6px 12px;\n  border: 1px dashed var(--muted);\n  border-radius: var(--radius);\n  color: var(--muted);\n  font-size: 0.875rem;\n  line-height: 1.5;\n  vertical-align: middle;\n}\n.mdv-ph .mdv-icon { width: 18px; height: 18px; }\n.mdv-ph-text { min-width: 0; overflow-wrap: anywhere; }\n\n/* 見つからない文書・添付 */\n\n.mdv-empty { padding: 32px 0; }\n.mdv-empty-title { margin: 0 0 12px; font-family: var(--font-display); font-size: 1.75rem; font-weight: 700; line-height: 1.4; }\n.mdv-empty-body { margin: 0 0 24px; color: var(--ink-soft); }\n.mdv-empty code { padding: 0.12em 0.36em; border-radius: 4px; background: var(--code-bg); font-family: var(--font-mono); font-size: 0.875em; }\n\n/* ------------------------------------------------------------------ 印刷: 常にライト配色 / Print: always light colors */\n\n/* セレクターを二重にして詳細度を上げ、このファイルの後ろに足した配色の指定より優先させる */\n@media print {\n  :root:root,\n  [data-theme][data-theme] {\n    --desk: #FFFFFF; --sheet: #FFFFFF; --ink: #000000; --ink-soft: #222222; --muted: #555555;\n    --rule: #BBBBBB; --rule-soft: #DDDDDD; --accent: #1D4F91; --accent-strong: #163D72; --accent-soft: #FFFFFF;\n    --mark: #FFE27A; --mark-ink: #000000; --code-bg: #F5F5F5;\n    --note: #1D4F91; --tip: #1B7F5A; --important: #6B4BA8; --warning: #8A5A00; --caution: #B3261E;\n    --hl-keyword: #8A2D6B; --hl-string: #1B6B4A; --hl-number: #9A4E00; --hl-comment: #5C6A7B;\n    --hl-title: #1D4F91; --hl-attr: #0B6E80; --hl-builtin: #6B4BA8; --hl-add-bg: #DDF3E4; --hl-del-bg: #FBE3E1;\n    color-scheme: light;\n  }\n  .mdv-prose { contain: none; margin: 0; padding: 0; }\n  .mdv-prose pre, .mdv-plain { white-space: pre-wrap; word-break: break-all; overflow: visible; }\n  .mdv-table-wrap, .math-display, .mdv-mermaid { overflow: visible; }\n  .mdv-prose h1, .mdv-prose h2, .mdv-prose h3, .mdv-prose h4 { break-after: avoid; }\n  .mdv-code, .mdv-prose pre, .mdv-prose table, .mdv-prose img, .mdv-mermaid, .markdown-alert { break-inside: avoid; }\n  .mdv-prose a.mdv-ext::after { content: none; }\n}\n"};
